#include <Adafruit_NeoPixel.h>

#define LED_PIN    6   // Arduino digital pin connected to NeoPixel DI
#define NUM_LEDS  28   // Total number of LEDs in your NeoPixel strip or ring

// Initialize the NeoPixel object
// Argument 1 = Number of LEDs in strip
// Argument 2 = Arduino pin number (most are valid)
// Argument 3 = Pixel type flags, add together as needed (e.g., NEO_GRB + NEO_KHZ800)
Adafruit_NeoPixel strip(NUM_LEDS, LED_PIN, NEO_GRB + NEO_KHZ800);

void setup() {
  strip.begin();           // Initialize the NeoPixel strip object
  strip.show();            // Turn off all pixels ASAP
  strip.setBrightness(255); // Set global brightness (0 to 255)
}

void loop() {
  // Pattern 1: Solid Color Fills (Red, Green, Blue)
  colorFill(strip.Color(255, 0, 0), 50);   // Red
  delay(1000);
  colorFill(strip.Color(0, 255, 0), 50);   // Green
  delay(1000);
  colorFill(strip.Color(0, 0, 255), 50);   // Blue
  delay(1000);

  // Pattern 2: Theater Chase (Marquee style style)
  theaterChase(strip.Color(255, 255, 255), 50); // White
  theaterChase(strip.Color(255,   0,   0), 50); // Red

  // Pattern 3: Knight Rider / Cylon Scanner
  cylonScanner(strip.Color(255, 0, 0), 40); // Red Scanner

  // Pattern 4: Rainbow Cycle
  rainbowCycle(10); 
}

// ==========================================
// PATTERN FUNCTIONS
// ==========================================

// Pattern 1: Fill the pixels one after the other with a color
void colorFill(uint32_t color, int wait) {
  for(int i=0; i<strip.numPixels(); i++) {
    strip.setPixelColor(i, color);         // Set pixel index 'i' to color
    strip.show();                          // Refresh the physical strip
    delay(wait);
  }
}

// Pattern 2: Theater-style crawling lights
void theaterChase(uint32_t color, int wait) {
  for(int a=0; a<10; a++) {                // Repeat the chase loop 10 times
    for(int b=0; b<3; b++) {               // Cycle through 3 offset states
      strip.clear();                       // Turn off all pixels
      for(int c=b; c<strip.numPixels(); c += 3) {
        strip.setPixelColor(c, color);     // Turn on every third pixel
      }
      strip.show();
      delay(wait);
    }
  }
}

// Pattern 3: Back-and-forth eye scanner (Cylon / Knight Rider effect)
void cylonScanner(uint32_t color, int wait) {
  // Scan forward
  for(int i=0; i<strip.numPixels(); i++) {
    strip.clear();
    strip.setPixelColor(i, color);
    // Optional trailing effect (dimmer adjacent pixels)
    if(i > 0) strip.setPixelColor(i-1, scaleColor(color, 0.2)); 
    strip.show();
    delay(wait);
  }
  // Scan backward
  for(int i=strip.numPixels()-1; i>=0; i--) {
    strip.clear();
    strip.setPixelColor(i, color);
    if(i < strip.numPixels()-1) strip.setPixelColor(i+1, scaleColor(color, 0.2));
    strip.show();
    delay(wait);
  }
}

// Pattern 4: Smoothly flows a rainbow across the entire length
void rainbowCycle(int wait) {
  for(long firstPixelHue = 0; firstPixelHue < 5*65536; firstPixelHue += 256) {
    for(int i=0; i<strip.numPixels(); i++) {
      int pixelHue = firstPixelHue + (i * 65536 / strip.numPixels());
      strip.setPixelColor(i, strip.gamma32(strip.ColorHSV(pixelHue)));
    }
    strip.show();
    delay(wait);
  }
}

// Helper Function: Scales an RGB color down to create a dim trailing effect
uint32_t scaleColor(uint32_t color, float factor) {
  uint8_t r = (uint8_t)((color >> 16) & 0xFF) * factor;
  uint8_t g = (uint8_t)((color >> 8) & 0xFF) * factor;
  uint8_t b = (uint8_t)(color & 0xFF) * factor;
  return strip.Color(r, g, b);
}
